-- FS-008E: database-owned, transactional admin procurement commands.
begin;

alter table public.furnishing_procurement_lines drop constraint if exists furnishing_procurement_lines_baseline_id_source_plan_line_id_key;
create unique index if not exists furnishing_procurement_plan_line_unique on public.furnishing_procurement_lines(baseline_id,source_plan_line_id) where source_plan_line_id is not null;
create unique index if not exists furnishing_procurement_snapshot_line_unique on public.furnishing_procurement_lines(baseline_id,source_snapshot_item_id) where source_snapshot_item_id is not null;

create or replace function public.create_or_replay_procurement_baseline(p_input jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid(); k text:=p_input->>'source_kind'; sid uuid; expected integer; command_key text:=left(trim(p_input->>'idempotency_key'),200); correlation uuid; p record; src record; b record; source_version integer; source_hash text; source_data jsonb; currency_code text; subtotal bigint:=0; shipping bigint:=0; tax bigint:=0; line_count integer;
begin
 if a is null or not public.is_admin() then raise exception 'PROCUREMENT_ADMIN_REQUIRED' using errcode='42501'; end if;
 begin sid:=(p_input->>'source_id')::uuid; expected:=(p_input->>'expected_source_version')::integer; correlation:=(p_input->>'correlation_id')::uuid; exception when others then raise exception 'PROCUREMENT_BASELINE_COMMAND_INVALID'; end;
 if k not in('furnishing_plan','catalog_snapshot') or expected<1 or length(command_key)<8 then raise exception 'PROCUREMENT_BASELINE_COMMAND_INVALID'; end if;
 if k='furnishing_plan' then
  select * into src from public.furnishing_plans where id=sid for update;
  if not found then raise exception 'PROCUREMENT_SOURCE_NOT_FOUND'; end if;
  select * into p from public.furnishing_projects where id=src.project_id for update;
  if not found or src.status<>'approved' or src.approved_at is null or src.approval_snapshot is null then raise exception 'FS006_APPROVED_PLAN_REQUIRED'; end if;
  if src.version_number<>expected then raise exception 'PROCUREMENT_SOURCE_VERSION_STALE'; end if;
  if exists(select 1 from public.furnishing_product_selections s left join public.furnishing_rooms r on r.id=s.room_id left join public.furnishing_products pr on pr.id=s.product_id left join public.furnishing_product_offers o on o.id=s.selected_offer_id where s.furnishing_plan_id=sid and(r.project_id is distinct from p.id or pr.id is null or(o.id is not null and o.product_id is distinct from pr.id))) then raise exception 'PROCUREMENT_SOURCE_LINEAGE_INVALID'; end if;
  source_version:=src.version_number; source_hash:=src.id::text||':'||src.revision::text||':'||src.updated_at::text; currency_code:=src.currency; subtotal:=src.estimated_subtotal_minor; shipping:=src.estimated_shipping_minor; tax:=src.estimated_tax_minor;
  source_data:=jsonb_build_object('package',src.package_snapshot,'design',src.design_snapshot,'approval',src.approval_snapshot,'planVersion',source_version);
 else
  select s.*,v.version_number into src from public.fs008d_project_catalog_snapshots s join public.furnishing_package_versions v on v.id=s.package_version_id where s.id=sid for update of s;
  if not found then raise exception 'PROCUREMENT_SOURCE_NOT_FOUND'; end if;
  select * into p from public.furnishing_projects where id=src.project_id for update;
  if not found or src.tenant_id is distinct from p.workspace_id then raise exception 'PROCUREMENT_SOURCE_SCOPE_INVALID'; end if;
  if src.version_number<>expected then raise exception 'PROCUREMENT_SOURCE_VERSION_STALE'; end if;
  if coalesce(src.content_hash,'')='' or not exists(select 1 from public.fs008d_snapshot_items where snapshot_id=sid) then raise exception 'PROCUREMENT_SNAPSHOT_NOT_NORMALIZED'; end if;
  if exists(select 1 from public.fs008d_snapshot_items i left join public.furnishing_rooms r on r.id=i.room_id left join public.furnishing_products pr on pr.id=i.product_id left join public.furnishing_product_offers o on o.id=i.retailer_offer_id where i.snapshot_id=sid and(i.tenant_id is distinct from p.workspace_id or i.project_id is distinct from p.id or r.project_id is distinct from p.id or pr.id is null or o.id is null or o.product_id is distinct from pr.id or i.observed_price_minor is null)) then raise exception 'PROCUREMENT_SNAPSHOT_NOT_NORMALIZED'; end if;
  if (select count(distinct i.currency) from public.fs008d_snapshot_items i where i.snapshot_id=sid)>1 then raise exception 'PROCUREMENT_SOURCE_CURRENCY_MISMATCH'; end if;
  source_version:=src.version_number; source_hash:=src.content_hash; select min(i.currency),coalesce(sum(i.extended_product_cost_minor),0),coalesce(sum(i.delivery_minor),0) into currency_code,subtotal,shipping from public.fs008d_snapshot_items i where i.snapshot_id=sid;
  source_data:=jsonb_build_object('catalogSnapshotId',sid,'packageVersionId',src.package_version_id,'version',source_version,'contentHash',source_hash);
 end if;
 perform pg_advisory_xact_lock(hashtextextended(p.workspace_id::text||':'||sid::text,0));
 select * into b from public.furnishing_procurement_baselines x where(k='furnishing_plan' and x.source_plan_id=sid)or(k='catalog_snapshot' and x.source_catalog_snapshot_id=sid) for update;
 if found then
  if b.source_kind<>k or b.source_plan_version<>expected or b.source_hash<>source_hash or b.idempotency_key<>command_key then raise exception 'PROCUREMENT_BASELINE_REPLAY_CONFLICT'; end if;
  return jsonb_build_object('status','replayed','id',b.id,'project_id',b.project_id,'version',b.version,'source_hash',b.source_hash);
 end if;
 if exists(select 1 from public.furnishing_procurement_baselines x where x.workspace_id=p.workspace_id and x.idempotency_key=command_key) then raise exception 'PROCUREMENT_BASELINE_REPLAY_CONFLICT'; end if;
 insert into public.furnishing_procurement_baselines(workspace_id,property_id,project_id,source_kind,source_plan_id,source_catalog_snapshot_id,source_plan_version,source_snapshot,source_hash,currency,status,estimated_subtotal_minor,estimated_shipping_minor,estimated_tax_minor,estimated_total_minor,idempotency_key,created_by)
 values(p.workspace_id,p.property_id,p.id,k,case when k='furnishing_plan' then sid end,case when k='catalog_snapshot' then sid end,source_version,source_data,source_hash,currency_code,'draft',subtotal,shipping,tax,subtotal+shipping+tax,command_key,a) returning * into b;
 if k='furnishing_plan' then
  insert into public.furnishing_procurement_lines(baseline_id,source_line_kind,source_plan_line_id,room_id,product_id,selected_offer_id,category,description,planned_quantity,existing_inventory_quantity,estimated_unit_cost_minor,estimated_line_cost_minor,currency,source_snapshot)
  select b.id,'plan_selection',s.id,s.room_id,s.product_id,s.selected_offer_id,pr.category,coalesce(nullif(s.requirement_name,''),pr.name),coalesce(s.quantity_override,s.resolved_quantity),s.existing_quantity,s.estimated_unit_price_minor,s.estimated_total_minor,s.currency,jsonb_build_object('selectionStatus',s.selection_status,'priority',s.priority,'quantityRuleId',s.quantity_rule_id,'offerId',s.selected_offer_id) from public.furnishing_product_selections s join public.furnishing_products pr on pr.id=s.product_id where s.furnishing_plan_id=sid and coalesce(s.quantity_override,s.resolved_quantity)>0;
 else
  insert into public.furnishing_procurement_lines(baseline_id,source_line_kind,source_snapshot_item_id,room_id,product_id,selected_offer_id,category,description,planned_quantity,existing_inventory_quantity,estimated_unit_cost_minor,estimated_line_cost_minor,currency,source_snapshot)
  select b.id,'snapshot_item',i.id,i.room_id,i.product_id,i.retailer_offer_id,pr.category,pr.name,i.quantity,0,i.observed_price_minor,i.extended_product_cost_minor,i.currency,jsonb_build_object('stableItemId',i.stable_item_id,'contentHash',i.content_hash,'deliveryMinor',i.delivery_minor,'sourceLineage',i.source_lineage) from public.fs008d_snapshot_items i join public.furnishing_products pr on pr.id=i.product_id where i.snapshot_id=sid;
 end if;
 get diagnostics line_count=row_count; if line_count=0 then raise exception 'PROCUREMENT_SOURCE_HAS_NO_LINES'; end if;
 insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,resulting_version,policy_version,related_type,related_id,payload) values(b.id,p.workspace_id,p.property_id,p.id,a,correlation,'procurement_baseline_generated',1,'fs008e-v1',k,sid,jsonb_build_object('sourceVersion',source_version,'sourceHash',source_hash,'lineCount',line_count));
 return jsonb_build_object('status','created','id',b.id,'project_id',p.id,'version',1,'source_hash',source_hash);
end $$;

create or replace function public.approve_furnishing_procurement_plan(p_input jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid(); target uuid; expected bigint; correlation uuid; command_key text:=left(trim(p_input->>'idempotency_key'),200); batch record; base record;
begin
 if a is null or not public.is_admin() then raise exception 'PROCUREMENT_ADMIN_REQUIRED' using errcode='42501'; end if; begin target:=(p_input->>'batch_id')::uuid; expected:=(p_input->>'expected_version')::bigint; correlation:=(p_input->>'correlation_id')::uuid; exception when others then raise exception 'PROCUREMENT_APPROVAL_COMMAND_INVALID'; end;
 select * into batch from public.furnishing_purchase_batches where id=target for update; if not found then raise exception 'PROCUREMENT_BATCH_NOT_FOUND'; end if; select * into base from public.furnishing_procurement_baselines where id=batch.baseline_id for update;
 if batch.status='authorized' then if batch.authorization_snapshot->>'idempotencyKey'=command_key then return jsonb_build_object('status','replayed','id',batch.id,'version',batch.version); end if; raise exception 'PROCUREMENT_APPROVAL_REPLAY_CONFLICT'; end if;
 if batch.version<>expected then raise exception 'PROCUREMENT_VERSION_STALE'; end if; if batch.status<>'submitted' then raise exception 'PROCUREMENT_BATCH_NOT_SUBMITTED'; end if; if batch.submitted_by=a then raise exception 'PROCUREMENT_APPROVAL_REQUIRES_DIFFERENT_ACTOR'; end if;
 update public.furnishing_purchase_batches set status='authorized',authorized_by=a,authorized_at=now(),authorization_snapshot=jsonb_build_object('idempotencyKey',command_key,'approvedAt',now()),version=version+1 where id=batch.id;
 update public.furnishing_procurement_lines l set status='authorized',revision=revision+1 where exists(select 1 from public.furnishing_purchase_batch_lines bl where bl.batch_id=batch.id and bl.line_id=l.id); update public.furnishing_procurement_baselines set status='authorized',version=version+1 where id=base.id;
 insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,previous_version,resulting_version,policy_version,related_type,related_id,payload) values(base.id,base.workspace_id,base.property_id,base.project_id,a,correlation,'purchase_batch_authorized',base.version,base.version+1,'fs008e-v1','purchase_batch',batch.id,jsonb_build_object('batchVersion',batch.version+1));
 return jsonb_build_object('status','authorized','id',batch.id,'version',batch.version+1);
end $$;

create or replace function public.create_or_replay_procurement_batch(p_input jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid(); baseline_id uuid; retailer_id uuid; expected bigint; correlation uuid; command_key text:=left(trim(p_input->>'idempotency_key'),200); base record; budget record; batch record; destination record; subtotal bigint; currency_code text; line_count integer;
begin
 if a is null or not public.is_admin() then raise exception 'PROCUREMENT_ADMIN_REQUIRED' using errcode='42501'; end if; begin baseline_id:=(p_input->>'baseline_id')::uuid; retailer_id:=(p_input->>'retailer_id')::uuid; expected:=(p_input->>'expected_version')::bigint; correlation:=(p_input->>'correlation_id')::uuid; exception when others then raise exception 'PROCUREMENT_BATCH_COMMAND_INVALID'; end;
 select * into base from public.furnishing_procurement_baselines where id=baseline_id for update; if not found then raise exception 'PROCUREMENT_BASELINE_NOT_FOUND'; end if; select * into batch from public.furnishing_purchase_batches where baseline_id=base.id and idempotency_key=command_key for update;
 if found then if batch.retailer_id=retailer_id then return jsonb_build_object('status','replayed','id',batch.id,'version',batch.version); end if; raise exception 'PROCUREMENT_BATCH_REPLAY_CONFLICT'; end if;
 if base.version<>expected then raise exception 'PROCUREMENT_VERSION_STALE'; end if; if base.status not in('draft','authorized','active') then raise exception 'PROCUREMENT_BASELINE_STATE_INVALID'; end if; if not exists(select 1 from public.furnishing_retailers where id=retailer_id and status='active') then raise exception 'PROCUREMENT_RETAILER_INVALID'; end if;
 select * into budget from public.furnishing_project_procurement_budgets where baseline_id=base.id and status in('submitted','approved','active') order by version desc limit 1 for update; if not found then raise exception 'FS006_BUDGET_REQUIRED'; end if; select * into destination from public.properties where id=base.property_id;
 select coalesce(sum(l.estimated_line_cost_minor),0),min(l.currency),count(*) into subtotal,currency_code,line_count from public.furnishing_procurement_lines l join public.furnishing_product_offers o on o.id=l.selected_offer_id where l.baseline_id=base.id and l.status in('planned','ready') and o.retailer_id=retailer_id and o.status='active' and o.availability<>'out_of_stock'; if line_count=0 then raise exception 'FS006_NO_ELIGIBLE_LINES'; end if;
 insert into public.furnishing_purchase_batches(baseline_id,budget_id,retailer_id,delivery_destination,status,subtotal_minor,total_minor,currency,readiness_snapshot,idempotency_key,created_by,submitted_by) values(base.id,budget.id,retailer_id,jsonb_build_object('address',destination.address_line_1,'city',destination.city,'state',destination.state,'postal_code',destination.postal_code,'country',destination.country),'submitted',subtotal,subtotal,currency_code,jsonb_build_object('lineCount',line_count,'evaluatedAt',now()),command_key,a,a) returning * into batch;
 insert into public.furnishing_purchase_batch_lines(batch_id,line_id,quantity,confirmed_unit_price_minor,offer_confirmation) select batch.id,l.id,l.procurement_quantity,o.listed_price_minor,jsonb_build_object('offerId',o.id,'productId',o.product_id,'listedPriceMinor',o.listed_price_minor,'availability',o.availability,'verifiedAt',o.last_verified_at) from public.furnishing_procurement_lines l join public.furnishing_product_offers o on o.id=l.selected_offer_id where l.baseline_id=base.id and l.status in('planned','ready') and o.retailer_id=retailer_id and o.status='active' and o.availability<>'out_of_stock';
 update public.furnishing_procurement_baselines set status='under_review',version=version+1 where id=base.id; insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,previous_version,resulting_version,policy_version,related_type,related_id,payload) values(base.id,base.workspace_id,base.property_id,base.project_id,a,correlation,'purchase_batch_submitted',base.version,base.version+1,'fs008e-v1','purchase_batch',batch.id,jsonb_build_object('retailerId',retailer_id,'lineCount',line_count,'totalMinor',subtotal));
 return jsonb_build_object('status','created','id',batch.id,'version',1,'baseline_version',base.version+1);
end $$;

create or replace function public.record_external_retailer_order(p_input jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid(); batch_id uuid; expected bigint; correlation uuid; external_id text:=left(trim(p_input->>'external_order_id'),200); command_key text:=left(trim(p_input->>'idempotency_key'),200); placed date; batch record; base record; retailer record; ord record;
begin
 if a is null or not public.is_admin() then raise exception 'PROCUREMENT_ADMIN_REQUIRED' using errcode='42501'; end if; begin batch_id:=(p_input->>'batch_id')::uuid; expected:=(p_input->>'expected_version')::bigint; correlation:=(p_input->>'correlation_id')::uuid; placed:=coalesce(nullif(p_input->>'order_date','')::date,current_date); exception when others then raise exception 'EXTERNAL_ORDER_COMMAND_INVALID'; end; if length(external_id)=0 or length(command_key)<8 then raise exception 'EXTERNAL_ORDER_COMMAND_INVALID'; end if;
 select * into batch from public.furnishing_purchase_batches where id=batch_id for update; if not found then raise exception 'PROCUREMENT_BATCH_NOT_FOUND'; end if; select * into base from public.furnishing_procurement_baselines where id=batch.baseline_id for update; select * into retailer from public.furnishing_retailers where id=batch.retailer_id; select * into ord from public.furnishing_procurement_orders where batch_id=batch.id for update;
 if found then if ord.external_order_id=external_id and ord.evidence->>'idempotencyKey'=command_key then return jsonb_build_object('status','replayed','id',ord.id,'version',ord.version); end if; raise exception 'EXTERNAL_ORDER_REPLAY_CONFLICT'; end if;
 if batch.version<>expected then raise exception 'PROCUREMENT_VERSION_STALE'; end if; if batch.status<>'authorized' then raise exception 'PROCUREMENT_BATCH_NOT_AUTHORIZED'; end if;
 insert into public.furnishing_procurement_orders(project_id,baseline_id,batch_id,workspace_id,retailer_id,po_number,vendor,order_type,external_order_id,status,total,order_date,placed_at,authorized_total_minor,actual_total_minor,currency,evidence) values(base.project_id,base.id,batch.id,base.workspace_id,batch.retailer_id,'EXT-'||replace(gen_random_uuid()::text,'-',''),retailer.name,'external',external_id,'ordered',batch.total_minor/100.0,placed,now(),batch.total_minor,batch.total_minor,batch.currency,jsonb_build_object('idempotencyKey',command_key,'recordedAt',now())) returning * into ord;
 insert into public.furnishing_procurement_order_lines(order_id,procurement_line_id,snapshot,ordered_quantity,unit_price_minor,line_total_minor,currency) select ord.id,bl.line_id,bl.offer_confirmation,bl.quantity,bl.confirmed_unit_price_minor,round(bl.confirmed_unit_price_minor*bl.quantity),l.currency from public.furnishing_purchase_batch_lines bl join public.furnishing_procurement_lines l on l.id=bl.line_id where bl.batch_id=batch.id;
 update public.furnishing_purchase_batches set status='ordered',version=version+1 where id=batch.id; update public.furnishing_procurement_lines l set status='ordered',committed_quantity=bl.quantity,revision=l.revision+1 from public.furnishing_purchase_batch_lines bl where bl.batch_id=batch.id and l.id=bl.line_id; update public.furnishing_procurement_baselines set status='active',version=version+1 where id=base.id;
 insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,previous_version,resulting_version,policy_version,related_type,related_id,payload) values(base.id,base.workspace_id,base.property_id,base.project_id,a,correlation,'external_retailer_order_recorded',base.version,base.version+1,'fs008e-v1','order',ord.id,jsonb_build_object('batchId',batch.id,'externalOrderId',external_id,'totalMinor',batch.total_minor)); return jsonb_build_object('status','recorded','id',ord.id,'version',1);
end $$;

create or replace function public.transition_furnishing_procurement_order(p_input jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid(); target uuid; expected bigint; correlation uuid; next_status text:=p_input->>'status'; why text:=left(trim(p_input->>'reason'),500); command_key text:=left(trim(p_input->>'idempotency_key'),200); ord record; base record;
begin
 if a is null or not public.is_admin() then raise exception 'PROCUREMENT_ADMIN_REQUIRED' using errcode='42501'; end if; begin target:=(p_input->>'order_id')::uuid; expected:=(p_input->>'expected_version')::bigint; correlation:=(p_input->>'correlation_id')::uuid; exception when others then raise exception 'ORDER_TRANSITION_COMMAND_INVALID'; end;
 select * into ord from public.furnishing_procurement_orders where id=target for update; if not found then raise exception 'PROCUREMENT_ORDER_NOT_FOUND'; end if; select * into base from public.furnishing_procurement_baselines where id=ord.baseline_id for update;
 if ord.evidence->>'idempotencyKey'=command_key then if ord.status=next_status then return jsonb_build_object('status','replayed','id',ord.id,'version',ord.version); end if; raise exception 'PROCUREMENT_ORDER_REPLAY_CONFLICT'; end if;
 if length(command_key)<8 then raise exception 'ORDER_TRANSITION_COMMAND_INVALID'; end if; if ord.version<>expected then raise exception 'PROCUREMENT_VERSION_STALE'; end if;
 if not((ord.status='ordered' and next_status in('partially_fulfilled','shipped','delivered','cancelled'))or(ord.status='partially_fulfilled' and next_status in('shipped','delivered','cancelled'))or(ord.status='shipped' and next_status in('delivered','returned'))or(ord.status='delivered' and next_status in('returned','refunded'))or(ord.status='returned' and next_status='refunded')) then raise exception 'PROCUREMENT_ORDER_TRANSITION_INVALID'; end if; if next_status in('cancelled','returned','refunded') and length(why)=0 then raise exception 'PROCUREMENT_TRANSITION_REASON_REQUIRED'; end if;
 update public.furnishing_procurement_orders set status=next_status,version=version+1,updated_at=now(),evidence=evidence||jsonb_build_object('lastTransition',next_status,'reason',why,'idempotencyKey',command_key) where id=ord.id;
 insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,previous_version,resulting_version,reason,policy_version,related_type,related_id,payload) values(base.id,base.workspace_id,base.property_id,base.project_id,a,correlation,'procurement_order_transitioned',ord.version,ord.version+1,why,'fs008e-v1','order',ord.id,jsonb_build_object('from',ord.status,'to',next_status)); return jsonb_build_object('status',next_status,'id',ord.id,'version',ord.version+1);
end $$;

create or replace function public.record_furnishing_procurement_receipt(p_input jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid(); target uuid; expected bigint; correlation uuid; command_key text:=left(trim(p_input->>'idempotency_key'),200); received numeric; accepted numeric; condition_code text:=p_input->>'condition'; line record; base record; receipt record; disposition_code text;
begin
 if a is null or not public.is_admin() then raise exception 'PROCUREMENT_ADMIN_REQUIRED' using errcode='42501'; end if; begin target:=(p_input->>'line_id')::uuid; expected:=(p_input->>'expected_version')::bigint; correlation:=(p_input->>'correlation_id')::uuid; received:=(p_input->>'received_quantity')::numeric; accepted:=(p_input->>'accepted_quantity')::numeric; exception when others then raise exception 'RECEIPT_COMMAND_INVALID'; end; if received<0 or accepted<0 or accepted>received or condition_code not in('good','damaged','missing_parts','wrong_item','other') then raise exception 'RECEIPT_COMMAND_INVALID'; end if;
 select * into line from public.furnishing_procurement_lines where id=target for update; if not found then raise exception 'PROCUREMENT_LINE_NOT_FOUND'; end if; select * into base from public.furnishing_procurement_baselines where id=line.baseline_id for update; select * into receipt from public.furnishing_procurement_receipts where baseline_id=base.id and idempotency_key=command_key for update;
 if found then if receipt.evidence->>'lineId'=target::text and(receipt.evidence->>'receivedQuantity')::numeric=received and(receipt.evidence->>'acceptedQuantity')::numeric=accepted then return jsonb_build_object('status','replayed','id',receipt.id,'line_version',line.revision); end if; raise exception 'PROCUREMENT_RECEIPT_REPLAY_CONFLICT'; end if;
 if line.revision<>expected then raise exception 'PROCUREMENT_VERSION_STALE'; end if; if line.status not in('ordered','partially_fulfilled') then raise exception 'PROCUREMENT_LINE_NOT_RECEIVABLE'; end if; if line.received_quantity+received>line.procurement_quantity or line.accepted_quantity+accepted>line.procurement_quantity then raise exception 'PROCUREMENT_RECEIPT_QUANTITY_EXCEEDED'; end if;
 insert into public.furnishing_procurement_receipts(baseline_id,status,evidence,notes,received_by,idempotency_key) values(base.id,case when condition_code<>'good' or accepted<received then 'exception' when line.accepted_quantity+accepted>=line.procurement_quantity then 'complete' else 'partial' end,jsonb_build_object('lineId',target,'receivedQuantity',received,'acceptedQuantity',accepted,'condition',condition_code),left(trim(p_input->>'reason'),500),a,command_key) returning * into receipt;
 disposition_code:=case condition_code when 'good' then 'accepted' when 'wrong_item' then 'incorrect_product' else 'damaged' end; if received>0 then insert into public.furnishing_procurement_receipt_lines(receipt_id,procurement_line_id,quantity,disposition,evidence) values(receipt.id,line.id,received,disposition_code,jsonb_build_object('condition',condition_code,'acceptedQuantity',accepted)); end if;
 update public.furnishing_procurement_lines set received_quantity=received_quantity+received,accepted_quantity=accepted_quantity+accepted,status=case when accepted_quantity+accepted>=procurement_quantity then 'fulfilled' when accepted_quantity+accepted>0 then 'partially_fulfilled' else status end,revision=revision+1 where id=line.id;
 if condition_code<>'good' or received>accepted then insert into public.furnishing_procurement_exceptions(baseline_id,line_id,exception_type,severity,detail) values(base.id,line.id,case when condition_code<>'good' then condition_code else 'shortage' end,case when condition_code<>'good' then 'blocking' else 'warning' end,jsonb_build_object('receiptId',receipt.id,'receivedQuantity',received,'acceptedQuantity',accepted,'condition',condition_code)); end if;
 insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,previous_version,resulting_version,policy_version,related_type,related_id,payload) values(base.id,base.workspace_id,base.property_id,base.project_id,a,correlation,'procurement_receipt_recorded',line.revision,line.revision+1,'fs008e-v1','receipt',receipt.id,receipt.evidence); return jsonb_build_object('status','recorded','id',receipt.id,'line_version',line.revision+1);
end $$;

create or replace function public.reconcile_furnishing_procurement_budget(p_input jsonb) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare a uuid:=auth.uid(); target uuid; expected bigint; correlation uuid; command_key text:=left(trim(p_input->>'idempotency_key'),200); base_amount bigint; contingency bigint; base record; prior record; budget record; actual bigint; committed bigint; next_version bigint;
begin
 if a is null or not public.is_admin() then raise exception 'PROCUREMENT_ADMIN_REQUIRED' using errcode='42501'; end if; begin target:=(p_input->>'baseline_id')::uuid; expected:=(p_input->>'expected_version')::bigint; correlation:=(p_input->>'correlation_id')::uuid; base_amount:=(p_input->>'base_amount_minor')::bigint; contingency:=(p_input->>'contingency_minor')::bigint; exception when others then raise exception 'BUDGET_RECONCILIATION_COMMAND_INVALID'; end; if base_amount<0 or contingency<0 or length(command_key)<8 then raise exception 'BUDGET_RECONCILIATION_COMMAND_INVALID'; end if;
 select * into base from public.furnishing_procurement_baselines where id=target for update; if not found then raise exception 'PROCUREMENT_BASELINE_NOT_FOUND'; end if;
 if base.source_snapshot->>'lastBudgetIdempotencyKey'=command_key then select * into budget from public.furnishing_project_procurement_budgets where id=(base.source_snapshot->>'lastBudgetId')::uuid; if budget.base_amount_minor=base_amount and budget.contingency_minor=contingency then return jsonb_build_object('status','replayed','id',budget.id,'version',budget.version); end if; raise exception 'PROCUREMENT_BUDGET_REPLAY_CONFLICT'; end if;
 if base.version<>expected then raise exception 'PROCUREMENT_VERSION_STALE'; end if; select * into prior from public.furnishing_project_procurement_budgets where baseline_id=base.id order by version desc limit 1 for update; next_version:=coalesce(prior.version,0)+1; select coalesce(sum(actual_total_minor),0),coalesce(sum(authorized_total_minor),0) into actual,committed from public.furnishing_procurement_orders where baseline_id=base.id and status not in('cancelled','refunded');
 insert into public.furnishing_project_procurement_budgets(baseline_id,workspace_id,property_id,project_id,currency,status,base_amount_minor,contingency_minor,committed_minor,gross_actual_minor,forecast_final_minor,version,submitted_by,submitted_at,created_by) values(base.id,base.workspace_id,base.property_id,base.project_id,base.currency,'submitted',base_amount,contingency,committed,actual,greatest(actual,committed),next_version,a,now(),a) returning * into budget;
 update public.furnishing_procurement_baselines set source_snapshot=source_snapshot||jsonb_build_object('lastBudgetId',budget.id,'lastBudgetIdempotencyKey',command_key),version=version+1 where id=base.id; insert into public.furnishing_procurement_events(baseline_id,workspace_id,property_id,project_id,actor_id,correlation_id,event_type,previous_version,resulting_version,policy_version,related_type,related_id,payload) values(base.id,base.workspace_id,base.property_id,base.project_id,a,correlation,'procurement_budget_reconciled',base.version,base.version+1,'fs008e-v1','budget',budget.id,jsonb_build_object('baseAmountMinor',base_amount,'contingencyMinor',contingency,'committedMinor',committed,'grossActualMinor',actual,'idempotencyKey',command_key)); return jsonb_build_object('status','submitted','id',budget.id,'version',budget.version,'baseline_version',base.version+1);
end $$;

drop function if exists public.create_or_replay_snapshot_procurement_baseline(uuid,text,text);
revoke all on function public.create_or_replay_procurement_baseline(jsonb),public.approve_furnishing_procurement_plan(jsonb),public.create_or_replay_procurement_batch(jsonb),public.record_external_retailer_order(jsonb),public.transition_furnishing_procurement_order(jsonb),public.record_furnishing_procurement_receipt(jsonb),public.reconcile_furnishing_procurement_budget(jsonb) from public,anon;
grant execute on function public.create_or_replay_procurement_baseline(jsonb),public.approve_furnishing_procurement_plan(jsonb),public.create_or_replay_procurement_batch(jsonb),public.record_external_retailer_order(jsonb),public.transition_furnishing_procurement_order(jsonb),public.record_furnishing_procurement_receipt(jsonb),public.reconcile_furnishing_procurement_budget(jsonb) to authenticated;
commit;
